() => {
  // Check what AppChrome sees â€” try to access React devtools state
  // Simpler: inspect what's actually rendered
  const html = document.documentElement.outerHTML;
  const hasBottomNavClass = html.includes('aria-label="Navigation principale"');
  const hasFabClass = html.includes('bottom-[90px]');
  const hasSOSClass = html.includes('fixed inset-0 z-[200]');
  return {
    htmlLen: html.length,
    hasBottomNav: hasBottomNavClass,
    hasFabPattern: hasFabClass,
    hasSOS: hasSOSClass,
    // React devtools internal
    hasReactRoot: !!document.getElementById('__next') || !!document.querySelector('#__NEXT_DATA__'),
  };
}

